namespace generic.stl;

class ReverseListIterator<T> : ListIterator<T> {

	ReverseListIterator(ListSTL<T> list, ListNodeSTL<T> root, ListNodeSTL<T> node) : base(list, root, node)
    {
	}
	
	/* @Override */
    public IteratorSTL<T> copy() {
		return new ReverseListIterator<T>( list, root, node );
	}

	/* @Override */
    public bool isBegin() {
		return node == root.prev;
	}
	
	/* @Override */
    public IteratorSTL<T> decrement() {
		if (node.prev == root) {
			throw new IndexOutOfBoundsException();
		}
		node = node.next;
		return this;
	}

	/* @Override */
    public IteratorSTL<T> increment() {
		node = node.prev;
		return this;
	}

	/* @Override */
    public void insert(T value) {
		ListNodeSTL<T> newNode = new ListNodeSTL<T>(node, node.next, value);
		node.next.prev = newNode;
		node.next = newNode;
		node = newNode;
		list.adjustSize(1);
	}

	/* @Override */
	public bool equals(object obj) {
		if (obj == null) {
			return false;
		}
